//! 🎟️ Actual original cancellation admission and metadata receipts match native heap effects.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn grants()->(RetainedCloneGrant,RetainedCloneGrant){let law:serde_json::Value=serde_json::from_str(crate::text("🛑️cancel/🎟️admission/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let read=|name:&str|{let p=law[name].as_array().unwrap();RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize}};(read("originalGrant"),read("closeGrant"))}
fn close(token:CancelToken,grant:RetainedCloneGrant)->usize{
 let(mut owner,heap)=observe(||CancelTokenRetirement::from_token(token));assert_eq!(heap,(0,0));let mut released=0;let mut turns=0;
 while !owner.terminal_is_empty(){let(demand,heap)=observe(||owner.retirement_demands().unwrap());assert_eq!(heap,(0,0));assert_eq!(demand.copy_bytes,0);
  for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:0,..grant}),(demand.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant})].into_iter().flatten(){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
  let(step,heap)=observe(||owner.close_step(grant).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!(p.copied_bytes,0);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));released+=p.released_bytes;turns+=1;assert!(turns<8);
 }assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(turns,2);released
}
#[test]
fn original_cancel_root_admission_uses_exact_native_birth_and_full_original_authority(){
 let(grant,close_grant)=grants();let(demand,heap)=observe(CancelToken::root_admission_demands);assert_eq!(heap,(0,0));assert_eq!((demand.copy_bytes,demand.release_bytes,demand.depth),(0,0,1));assert!(demand.capacity_bytes>0&&demand.capacity_bytes<=grant.maximum_capacity_bytes);
 for mask in 0..32{let incoming=RetainedCloneGrant{maximum_items:if mask&1!=0{0}else{grant.maximum_items},maximum_copy_bytes:if mask&2!=0{0}else{grant.maximum_copy_bytes},maximum_capacity_bytes:if mask&4!=0{0}else{grant.maximum_capacity_bytes},maximum_release_bytes:if mask&8!=0{0}else{grant.maximum_release_bytes},maximum_depth:if mask&16!=0{0}else{grant.maximum_depth}};let(result,heap)=observe(||CancelToken::admit_root(incoming).unwrap());if mask&(1|4|16)!=0{assert!(result.is_none());assert_eq!(heap,(0,0));continue;}let(token,p)=result.unwrap();assert!(p.fits(incoming));assert_eq!(p,RetainedCloneProgress{copied_items:1,retained_capacity_bytes:demand.capacity_bytes,..Default::default()});assert_eq!(heap,(p.retained_capacity_bytes,0));assert_eq!(token.0.parent.is_none(),true);assert!(!token.is_cancelled_now());assert_eq!(close(token,close_grant),p.retained_capacity_bytes);}
 eprintln!("[DEBUG] original cancellation native root denialShapes=32 birth={} metadataCopy0 queryHeap0 deniedHeap0 zeroCopyAndReleaseAdmit=true terminalDrop0",demand.capacity_bytes);
}
#[test]
fn original_cancel_child_admission_preserves_exact_parent_and_alias_receipts(){
 let(grant,close_grant)=grants();let(parent,parent_receipt)=CancelToken::admit_root(grant).unwrap().unwrap();let pointer=Arc::as_ptr(&parent.0);let strong=Arc::strong_count(&parent.0);let bytes=CancelToken::root_admission_demands().capacity_bytes;
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe(||parent.admit_child(denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(Arc::as_ptr(&parent.0),pointer);assert_eq!(Arc::strong_count(&parent.0),strong);}
 let(result,heap)=observe(||parent.admit_child(grant).unwrap());let(child,receipt)=result.unwrap();assert_eq!(heap,(receipt.retained_capacity_bytes,0));assert_eq!(receipt.copied_bytes,0);assert_eq!(receipt.retained_capacity_bytes,bytes);assert_eq!(Arc::as_ptr(&child.0.parent.as_ref().unwrap().0),pointer);assert_eq!(Arc::strong_count(&parent.0),strong+1);parent.cancel_now();assert!(child.is_cancelled_now());let mut owner=CancelTokenRetirement::from_token(child);
 let(step,heap)=observe(||owner.close_step(close_grant).unwrap());assert_eq!(heap,(0,bytes));assert_eq!(step.progress().copied_bytes,0);assert!(matches!(step,RetainedCloneStep::Progress(_)));
 let(step,heap)=observe(||owner.close_step(close_grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(owner.is_original_alias_witness(&parent));
 let(step,heap)=observe(||owner.return_alias_step(&parent,close_grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(owner.terminal_is_empty());assert_eq!(Arc::strong_count(&parent.0),strong);assert_eq!(Arc::as_ptr(&parent.0),pointer);assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(close(parent,close_grant),parent_receipt.retained_capacity_bytes);eprintln!("[DEBUG] original cancellation child birth={bytes} deniedOriginalParentUnchanged=true exactAncestorCancel=true metadataCopy0 originalAliasReturn0heap terminalDrop0");
}

#[test]
fn original_cancel_flag_preserves_live_waiter_ownership_and_actual_receipt(){
 let(grant,close_grant)=grants();let((token,birth),system)=observe(||CancelToken::admit_root(grant).unwrap().unwrap());assert_eq!(system,(birth.retained_capacity_bytes,0));let mut allocated=system.0;let mut released=0;let pointer=Arc::as_ptr(&token.0);let(mut future,system)=observe(||token.cancelled());assert_eq!(system,(0,0));let noop=std::task::Waker::noop();let mut context=Context::from_waker(noop);let(pending,system)=observe(||Pin::new(&mut future).poll(&mut context));assert!(pending.is_pending());allocated+=system.0;released+=system.1;let(waiter_pointer,waiter_capacity,waiter_length)={let waiters=token.0.waiters.lock();(waiters.as_ptr(),waiters.capacity(),waiters.len())};assert_eq!(waiter_length,1);
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,system)=observe(||token.signal_cancelled_flag_step(denied));assert!(result.is_none());assert_eq!(system,(0,0));assert!(!token.is_cancelled_now());assert_eq!(Arc::as_ptr(&token.0),pointer);let waiters=token.0.waiters.lock();assert_eq!((waiters.as_ptr(),waiters.capacity(),waiters.len()),(waiter_pointer,waiter_capacity,waiter_length));}
 let flag=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let(result,system)=observe(||token.signal_cancelled_flag_step(flag));let spent=result.unwrap();assert_eq!(spent,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(system,(0,0));assert!(token.is_cancelled_now());assert_eq!(Arc::as_ptr(&token.0),pointer);{let waiters=token.0.waiters.lock();assert_eq!((waiters.as_ptr(),waiters.capacity(),waiters.len()),(waiter_pointer,waiter_capacity,waiter_length));}assert!(Pin::new(&mut future).poll(&mut context).is_ready());assert_eq!(observe(||drop(future)).1,(0,0));let mut owner=CancelTokenRetirement::from_token(token);for turn in 0..8{if owner.terminal_is_empty(){break}let(step,system)=observe(||owner.close_step(close_grant).unwrap());assert_eq!(system,(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=system.0;released+=system.1;assert!(turn<7,"original flagged waiter owner closure stalled")}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(allocated,released);let oracle=serde_json::json!({"sameNode":true,"waiterPreserved":true,"spent":[1,0,0,0],"deniedHeap":[0,0],"flagHeap":[0,0],"terminalDrop":0});assert_eq!(oracle["spent"],serde_json::json!([spent.copied_items,spent.copied_bytes,spent.retained_capacity_bytes,spent.released_bytes]));eprintln!("[DEBUG] Actual original cancellation flag item1/copy0 preserves same node and live waiter backing, zero/depth denial System0, signal System0, later caller-funded complete waiter backing/node release, terminalDrop0");
}
